<?php
namespace App\Services;use App\Models\TransportService;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class TransportPassengerResolverService{public function resolve(TransportService$s,int$user):int{if($s->passenger_snapshot_status==='frozen')throw ValidationException::withMessages(['passengers'=>'La lista de pasajeros ya está congelada.']);$direction=$s->service_type==='pickup'?'outbound':($s->service_type==='dropoff'?'return':null);$query=$s->route->passengers()->wherePivot('status','active')->wherePivot('valid_from','<=',$s->service_date)->where(fn($q)=>$q->whereNull('transport_route_passengers.valid_until')->orWhere('transport_route_passengers.valid_until','>=',$s->service_date));if($direction)$query->wherePivotIn('direction',[$direction,'both']);$passengers=$query->get();DB::transaction(function()use($s,$passengers,$user){$manual=$s->passengers()->where('added_manually',true)->pluck('transport_passenger_id');$s->passengers()->where('added_manually',false)->delete();foreach($passengers as$p)if(!$manual->contains($p->id))$s->passengers()->create(['transport_passenger_id'=>$p->id,'transport_route_stop_id'=>$p->pivot->transport_route_stop_id,'passenger_name_snapshot'=>$p->name,'group_snapshot'=>$p->grade_group,'expected'=>true,'status'=>'expected']);$s->update(['passenger_snapshot_status'=>'resolved','updated_by'=>$user]);});return$s->passengers()->where('status','expected')->count();}public function confirm(TransportService$s,int$user):void{DB::transaction(function()use($s,$user){$s=TransportService::forCompany($s->company_id)->whereKey($s->id)->lockForUpdate()->firstOrFail();if(!in_array($s->status,['draft','scheduled'],true)||$s->passenger_snapshot_status!=='resolved')throw ValidationException::withMessages(['passengers'=>'Primero debe resolver y revisar la lista de pasajeros.']);$s->update(['passenger_snapshot_status'=>'frozen','updated_by'=>$user]);});}}
